<script setup lang="ts">
import { computed,onMounted,reactive,ref } from 'vue'
import { generarPadron, listarPadron, registrarVerificacion } from '../services/verificarCortados'
import type { Option, Suministro } from '../interfaces/verificarCortados.interface'
const rows=ref<Suministro[]>([]),distritos=ref<Option[]>([]),sectores=ref<Option[]>([]),calles=ref<Option[]>([]),observaciones=ref<Option[]>([]),dinamicas=ref<Option[]>([]),detail=ref<Suministro|null>(null),modal=ref(false),files=ref<File[]>([]),total=ref(0),lastPage=ref(1),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),progress=reactive({revisados:0,total:0})
const filters=reactive({distrito_id:'',sector_id:'',calle_id:'',criterio:'',estado:'pendientes',page:1}),form=reactive({resultado:'cortado',observacion_id:'',detalle:'',latitud:'',longitud:'',dinamicas:[] as number[]})
const percent=computed(()=>progress.total?Math.round(progress.revisados/progress.total*100):0)
async function load(page=1){filters.page=page;loading.value=true;error.value='';try{const r=await listarPadron(filters);rows.value=r.data;total.value=r.total;lastPage.value=r.last_page;distritos.value=r.distritos;sectores.value=r.sectores;calles.value=r.calles;observaciones.value=r.observaciones;dinamicas.value=r.dinamicas;Object.assign(progress,r.avance)}catch(e){error.value=msg(e)}finally{loading.value=false}}
function changeDistrict(){filters.sector_id='';filters.calle_id='';load(1)}function changeSector(){filters.calle_id='';load(1)}async function generate(){if(!filters.sector_id){error.value='Seleccione un sector.';return}if(!confirm('¿Generar el padrón de revisión para este sector?'))return;try{await generarPadron(Number(filters.sector_id));success.value='Padrón generado correctamente.';await load(1)}catch(e){error.value=msg(e)}}
function open(x:Suministro){detail.value=x;Object.assign(form,{resultado:'cortado',observacion_id:'',detalle:'',latitud:'',longitud:'',dinamicas:[]});files.value=[];modal.value=true;navigator.geolocation?.getCurrentPosition(p=>{form.latitud=String(p.coords.latitude);form.longitud=String(p.coords.longitude)})}
function pick(e:Event){files.value=Array.from((e.target as HTMLInputElement).files||[])}function toggle(id:number){form.dinamicas=form.dinamicas.includes(id)?form.dinamicas.filter(x=>x!==id):[...form.dinamicas,id]}
async function submit(){if(!detail.value)return;if(!form.resultado){error.value='Seleccione el resultado de la verificación.';return}saving.value=true;error.value='';try{const data=new FormData();Object.entries(form).forEach(([k,v])=>{if(k!=='dinamicas')data.append(k,String(v))});form.dinamicas.forEach(x=>data.append('dinamicas[]',String(x)));files.value.forEach(x=>data.append('fotografias[]',x));await registrarVerificacion(detail.value.id,data);success.value='Verificación registrada correctamente.';modal.value=false;detail.value=null;await load(filters.page)}catch(e){error.value=msg(e)}finally{saving.value=false}}function msg(e:unknown){return e instanceof Error?e.message:'No se pudo completar la operación.'}onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / EVAN / Cobranza / Verificación de cortados</nav><header class="hero"><div class="mark">VC</div><div><small>EVAN · COBRANZA</small><h1>Verificación de servicios cortados</h1><p>Padrón de campo, evidencias y situación actual del suministro.</p></div><div class="advance"><b>{{percent}}%</b><span>{{progress.revisados}} de {{progress.total}} revisados</span><i><em :style="{width:percent+'%'}"></em></i></div></header><p v-if="success" class="flash good">✓ {{success}}</p><p v-if="error" class="flash error">{{error}}</p><section class="filters"><label>Distrito<select v-model="filters.distrito_id" @change="changeDistrict"><option value="">Todos</option><option v-for="x in distritos" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Sector<select v-model="filters.sector_id" @change="changeSector"><option value="">Todos</option><option v-for="x in sectores" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Calle<select v-model="filters.calle_id"><option value="">Todas</option><option v-for="x in calles" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Estado<select v-model="filters.estado"><option value="pendientes">Pendientes</option><option value="revisados">Revisados</option><option value="">Todos</option></select></label><label>Buscar<input v-model.trim="filters.criterio" placeholder="SICI, suministro o cliente" @keyup.enter="load(1)"></label><button @click="load(1)">Consultar</button><button class="generate" @click="generate">Generar padrón</button></section><div v-if="loading" class="empty">Cargando padrón…</div><div v-else-if="!rows.length" class="empty">No existen suministros en la selección.</div><section v-else class="cards"><article v-for="x in rows" :key="x.id" :class="{done:x.registrado}"><header><div><small>SICI {{x.sici}}</small><b>{{x.cliente}}</b></div><em>{{x.registrado?'Revisado':'Pendiente'}}</em></header><p>{{x.direccion}}</p><dl><div><dt>Suministro</dt><dd>{{x.codigo}}</dd></div><div><dt>Medidor</dt><dd>{{x.medidor||'—'}}</dd></div><div><dt>Categoría</dt><dd>{{x.categoria}}</dd></div><div><dt>Situación</dt><dd>{{x.situacion||'Sin verificar'}}</dd></div></dl><div class="services"><span v-for="s in x.servicios" :key="s">{{s}}</span></div><footer><button v-if="!x.registrado" @click="open(x)">Registrar verificación</button><button v-else @click="detail=x">Ver verificación</button></footer></article></section><footer v-if="lastPage>1" class="pages"><button :disabled="filters.page<=1" @click="load(filters.page-1)">Anterior</button><span>{{filters.page}} / {{lastPage}}</span><button :disabled="filters.page>=lastPage" @click="load(filters.page+1)">Siguiente</button></footer>
<div v-if="detail&&!modal" class="backdrop" @mousedown.self="detail=null"><section class="modal"><header><div><small>SUMINISTRO {{detail.codigo}}</small><h2>{{detail.cliente}}</h2><p>{{detail.direccion}}</p></div><button @click="detail=null">×</button></header><div class="summary"><div><span>Situación</span><b>{{detail.situacion}}</b></div><div><span>Fecha de revisión</span><b>{{detail.fecha_revision||'—'}}</b></div></div><h3>Evidencias</h3><div class="photos"><a v-for="(x,i) in detail.fotografias" :key="i" :href="x" target="_blank">Fotografía {{i+1}}</a></div><footer><button class="clear" @click="detail=null">Cerrar</button></footer></section></div>
<div v-if="modal&&detail" class="backdrop" @mousedown.self="modal=false"><form class="modal wide" @submit.prevent="submit"><header><div><small>{{detail.codigo}} · {{detail.sici}}</small><h2>Registrar verificación</h2><p>{{detail.direccion}}</p></div><button type="button" @click="modal=false">×</button></header><div class="grid"><label>Resultado *<select v-model="form.resultado"><option value="cortado">Servicio cortado verificado</option><option value="activo">Servicio activo</option><option value="impedimento">No se pudo verificar</option><option value="corte_realizado">Corte realizado en campo</option></select></label><label>Observación<select v-model="form.observacion_id"><option value="">Seleccione</option><option v-for="x in observaciones" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Latitud<input v-model="form.latitud" readonly></label><label>Longitud<input v-model="form.longitud" readonly></label></div><label>Detalle<textarea v-model.trim="form.detalle" rows="3"></textarea></label><h3>Dinámica catastral</h3><div class="dynamics"><button v-for="x in dinamicas" :key="x.id" type="button" :class="{selected:form.dinamicas.includes(x.id)}" @click="toggle(x.id)">{{x.nombre}} {{form.dinamicas.includes(x.id)?'✓':''}}</button></div><label>Fotografías<input type="file" multiple accept="image/*" capture="environment" @change="pick"><small>{{files.length}} archivo(s) seleccionado(s)</small></label><footer><button type="button" class="clear" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Guardando…':'Finalizar verificación'}}</button></footer></form></div></div></template>
<style scoped>
.page{--a:#24855f;color:#34444d}nav{margin-bottom:16px;color:#96a1a7;font-size:.7rem}nav a{color:var(--a)}.hero{padding:22px 25px;display:flex;align-items:center;gap:15px;border-left:5px solid var(--a);border-radius:13px;background:#fff}.mark{width:52px;height:52px;display:grid;place-items:center;border-radius:11px;color:#fff;background:var(--a);font-weight:700}.hero small,.modal small,.cards small{color:var(--a);font-size:.55rem;font-weight:700}.hero h1{margin:2px 0;font-size:1.3rem}.hero p,.modal header p{margin:0;color:#7d898f;font-size:.65rem}.advance{margin-left:auto;width:160px}.advance b,.advance span{display:block;font-size:.55rem}.advance i{height:5px;display:block;background:#dbe5e1}.advance em{height:100%;display:block;background:var(--a)}.flash{padding:10px;font-size:.63rem}.good{color:#287258;background:#edf9f3}.error{color:#a13f43;background:#fff0f0}.filters{margin-top:13px;padding:12px;display:flex;align-items:end;gap:6px;background:#fff}.filters label{flex:1;font-size:.48rem}.filters button,.pages button,.modal footer button{padding:8px 10px;border:0;border-radius:5px;color:#fff;background:var(--a);font-size:.5rem}.filters .generate{background:#657a84}input,select,textarea{width:100%;padding:8px;border:1px solid #d8e0e4;border-radius:5px;font:inherit;font-size:.54rem}.cards{margin-top:12px;display:grid;grid-template-columns:repeat(3,1fr);gap:9px}.cards article{display:flex;flex-direction:column;padding:13px;border-top:3px solid #d28a3c;border-radius:8px;background:#fff}.cards article.done{border-color:var(--a)}.cards header{display:flex;justify-content:space-between}.cards header b,.cards header small{display:block;font-size:.52rem}.cards em{font-size:.44rem;font-style:normal}.cards>article>p{min-height:31px;color:#748087;font-size:.49rem}.cards dl{display:grid;grid-template-columns:1fr 1fr;gap:5px}.cards dt{color:#89949a;font-size:.42rem}.cards dd{margin:2px 0;font-size:.48rem;font-weight:700}.services span{margin:2px;padding:3px 5px;border-radius:5px;background:#eef3f1;font-size:.42rem}.cards footer{margin-top:auto}.cards footer button{width:100%;margin-top:9px;padding:7px;border:0;border-radius:5px;color:#fff;background:var(--a);font-size:.48rem}.empty{margin-top:12px;padding:45px;text-align:center;background:#fff;font-size:.6rem}.pages{display:flex;justify-content:center;align-items:center;gap:8px}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#15283a88}.modal{width:min(100%,700px);max-height:92vh;overflow:auto;padding:20px;border-radius:12px;background:#fff}.wide{width:min(100%,850px)}.modal>header{display:flex}.modal h2{margin:2px 0;font-size:1rem}.modal h3{font-size:.6rem}.modal>header>button{margin-left:auto;border:0;background:none;font-size:1.4rem}.modal label{display:block;margin:10px 0;font-size:.52rem}.grid,.summary{display:grid;grid-template-columns:1fr 1fr;gap:7px}.dynamics{display:grid;grid-template-columns:1fr 1fr}.dynamics button{padding:8px;border:1px solid #e1e6e8;background:#fff;text-align:left;font-size:.48rem}.dynamics button.selected{color:#26785b;background:#e9f8f1}.summary div{padding:10px;background:#f2f7f5}.summary span,.summary b{display:block;font-size:.52rem}.photos a{margin:3px;padding:6px;display:inline-block;color:var(--a);background:#edf7f3;font-size:.48rem}.modal footer{margin-top:13px;display:flex;justify-content:flex-end;gap:6px}.clear{color:#68757c!important;background:#edf1f3!important}@media(max-width:1000px){.filters{align-items:stretch;flex-wrap:wrap}.filters label{min-width:28%}.cards{grid-template-columns:1fr 1fr}}@media(max-width:560px){.cards,.grid,.summary,.dynamics{grid-template-columns:1fr}.hero{flex-wrap:wrap}.advance{margin-left:0;width:100%}.filters label{min-width:100%}}
</style>
